# carbon_iq/uncertainty.py :: Scenarios.decide()
    def decide(self, budget, target, alpha, mask=None, budget_reliability=None):
        """SAA chance-constrained choice on the scenarios in `mask`. Falls back to the highest target probability.

        Returns (k, E[NPV], P(target), feasible). With budget_reliability=b, portfolios must also stay within budget
        in at least a share b of the scenarios; if none qualifies, k is None."""
        m = np.ones(self.n, bool) if mask is None else mask
        cand = self.candidates(budget, budget_reliability, m)
        if not cand:
            return None, None, None, False
        en = {k: self.PNPV[k][m].mean() for k in cand}
        pt = {k: (self.PT12[k][m] >= target).mean() for k in cand}
        ok = [k for k in cand if pt[k] >= alpha - 1e-12]
        k = max(ok, key=lambda k: en[k]) if ok else max(cand, key=lambda k: (pt[k], en[k]))
        return k, en[k], pt[k], bool(ok)

# carbon_iq/engine.py :: npv()
def npv(capex, annual_cf, r, n):
    return -capex + annual_cf * annuity_factor(r, n)

# carbon_iq/engine.py :: irr()
def irr(capex, annual_cf, n, lo=-0.99, hi=1.0):
    """IRR of -capex followed by n equal flows (bisection). None if no sign change."""
    f = lambda r: -capex + annual_cf * float(annuity_factor(r, n))
    if f(lo) * f(hi) > 0:
        return None
    for _ in range(200):
        mid = (lo + hi) / 2
        if f(lo) * f(mid) <= 0:
            hi = mid
        else:
            lo = mid
    return (lo + hi) / 2

# carbon_iq/optimize.py :: greedy()
def greedy(prj, inter, budget, key, label, require_positive_npv=True):
    """Rank projects by `key` and fund down the list while budget allows (the usual one-by-one ranking)."""
    order = sorted(ALL, key=key)
    pick, spent = [], 0.0
    for i in order:
        if require_positive_npv and float(prj[i]["npv"]) <= 0:
            continue
        if spent + float(prj[i]["capex"]) <= budget + 1e-6:
            pick.append(i); spent += float(prj[i]["capex"])
    t = portfolio(pick, prj, inter)
    return {"method": label, "ids": tuple(sorted(pick)), "portfolio": "+".join(sorted(pick)) or "(none)",
            **{k: float(v) for k, v in t.items()}, "order": "".join(order)}

# carbon_iq/decisions.py :: capex_risk()
def capex_risk(sc, budget, target, alpha, levels=(0.8, 0.9, 0.95)):
    """Capital-cost risk table on the primary sample; `alpha` should already be the tightened level."""
    rows = []
    for st in sorted(sc.table(budget, target), key=lambda r: -r["e_npv"]):
        rows.append({k: (float(v) if isinstance(v, (float, np.floating)) else v) for k, v in st.items()
                     if k in ("portfolio", "capex", "e_capex", "p90_capex", "p95_capex", "p_over_budget",
                              "p_target", "p_target_and_budget", "e_npv", "contingency_p90")})
    variants = []
    for b in levels:
        k, e, pt, ok = sc.decide(budget, target, alpha, budget_reliability=b)
        variants.append({"budget_reliability": b, "portfolio": sc.name(k) if (k is not None and ok) else "none feasible",
                         "e_npv": _f(e) if ok else None, "p_target": _f(pt) if ok else None})
    # smallest budget at which the chance-constrained choice also stays within budget with 90% probability
    kc, *_ = sc.decide(budget, target, alpha)
    return {"table": rows, "with_budget_reliability": variants,
            "cc_portfolio": sc.name(kc), "cc_p90_capex": float(np.percentile(sc.PCAP[kc], 90)),
            "cc_contingency_p90": max(0.0, float(np.percentile(sc.PCAP[kc], 90)) - budget)}
